1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	  potion: 40,
32	  rune: 25,
33	};
34	
35	const COMPONENT_BLOCK_SIZE = 3;
36	const COMPONENT_BLOCK_PREMIUM = 60;
37	
38	const groupByType = (items: Item[]): Item[][] => {
39	  const groups = new Map<string, Item[]>();
40	  for (const item of items) {
41	    const group = groups.get(item.type) ?? [];
42	    group.push(item);
43	    groups.set(item.type, group);
44	  }
45	  return [...groups.values()];
46	};
47	
48	const formsBlock = (alikeItems: Item[]): boolean =>
49	  alikeItems.length === COMPONENT_BLOCK_SIZE;
50	
51	const basePremiumForAlikeItems = (alikeItems: Item[]): number => {
52	  if (formsBlock(alikeItems)) return COMPONENT_BLOCK_PREMIUM;
53	  return alikeItems.length * BASE_PREMIUMS[alikeItems[0].type];
54	};
55	
56	const totalBasePremium = (items: Item[]): number =>
57	  groupByType(items).reduce(
58	    (total, alikeItems) => total + basePremiumForAlikeItems(alikeItems),
59	    0,
60	  );
61	
62	const quotePremium = (items: Item[]): number => {
63	  const base = totalBasePremium(items);
64	  // Keep the surcharge additive (base + base * rate). The algebraically
65	  // equivalent base * (1 + rate) yields 110.00000000000001 for base 100,
66	  // which Math.ceil turns into a premium that is 1 G too high.
67	  const firstInsuranceSurcharge = base * FIRST_INSURANCE_SURCHARGE_RATE;
68	  return Math.ceil(base + firstInsuranceSurcharge + PROCESSING_FEE);
69	};
70	
71	export const runScenario = (scenario: Scenario): Result[] =>
72	  scenario.steps.map((step) => {
73	    if (step.op === "quote") return { premium: quotePremium(step.items) };
74	    throw new Error(`Unsupported step: ${step.op}`);
75	  });
