const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

/** Items that share the same `type`, and so are priced together. */
type AlikeItems = { type: string; count: number };

const groupByType = (items: Item[]): AlikeItems[] => {
  const countsByType = new Map<string, number>();
  for (const { type } of items) {
    countsByType.set(type, (countsByType.get(type) ?? 0) + 1);
  }
  return [...countsByType].map(([type, count]) => ({ type, count }));
};

const formsBlock = ({ count }: AlikeItems): boolean => count === BLOCK_SIZE;

const basePremiumFor = (alike: AlikeItems): number =>
  formsBlock(alike) ? BLOCK_PREMIUM : alike.count * BASE_PREMIUMS[alike.type];

const totalBasePremium = (items: Item[]): number =>
  groupByType(items).reduce((total, alike) => total + basePremiumFor(alike), 0);

