/** Items that share the same `type`, and so are priced together. */
type AlikeItems = { type: string; items: Item[] };

const groupByType = (items: Item[]): AlikeItems[] => {
  const itemsByType = new Map<string, Item[]>();
  for (const item of items) {
    itemsByType.set(item.type, [...(itemsByType.get(item.type) ?? []), item]);
  }
  return [...itemsByType].map(([type, alike]) => ({ type, items: alike }));
};

const formsBlock = ({ items }: AlikeItems): boolean => items.length === BLOCK_SIZE;

const basePremiumFor = (alike: AlikeItems): number =>
  formsBlock(alike) ? BLOCK_PREMIUM : alike.items.length * BASE_PREMIUMS[alike.type];
